// The second fence (Ahab's Python code is the first). An allowlist: only
// these requests, in Ahab's own Vercel account, pass. Deployments are
// previews of static files only: no target (so preview; but a project's
// very first deployment Vercel always makes production, which Ahab's code
// spends on a placeholder page), no Git,
// no settings, no build, no serverless functions (api/, middleware, config
// files). Production moves only by redeploying one existing deployment as
// production (its same files), the request Ahab's code sends only after the
// owner approves; Vercel's promote refuses previews, so it isn't allowed. No deleting,
// domains, aliases, environment variables, protection or bypass changes.
const NAME = '[a-z0-9][a-z0-9-]{0,39}';
const DPL = 'dpl_[A-Za-z0-9]{1,64}';
const PRJ = '(prj_[A-Za-z0-9]{1,64}|' + NAME + ')';
const r = $input.first().json.body || {};
const method = String(r.method || 'GET').toUpperCase();
const url = String(r.url || '');
const body = r.body ?? {};
const query = r.query || {};
const bodyText = JSON.stringify(body);
const base = 'https://api.vercel.com/';
const path = url.startsWith(base) ? url.slice(base.length) : null;
const allowed = [
  ['GET', /^v2\/user$/],
  ['GET', /^v9\/projects$/],
  ['GET', new RegExp('^v9/projects/' + PRJ + '$')],
  ['GET', new RegExp('^v9/projects/' + PRJ + '/domains$')],
  ['GET', /^v6\/deployments$/],
  ['GET', new RegExp('^v13/deployments/' + DPL + '$')],
  ['POST', /^v11\/projects$/],
  ['POST', /^v2\/files$/],
  ['POST', /^v13\/deployments$/],
];
const QUERY_KEYS = ['projectId', 'limit', 'since', 'until', 'skipAutoDetectionConfirmation'];
const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const only = (o, keys) => isObject(o) && Object.keys(o).every(k => keys.includes(k));
const SEGMENT = /^(?!\.\.?$)[A-Za-z0-9_.@()+,=~ -]+$/;
const RISKY = /^(api\/|\.vercel\/|_?middleware\.|(vercel|now|package)\.json$)/;
function badFile(f) {
  if (!only(f, ['file', 'sha', 'size']) || Object.keys(f).length !== 3) return 'each file must be just file, sha and size';
  const p = String(f.file);
  if (p.length > 255 || !p.split('/').every(s => SEGMENT.test(s))) return 'file paths must be plain relative paths';
  if (RISKY.test(p)) return p + ' would make Vercel run code or change settings';
  if (!/^[0-9a-f]{40}$/.test(String(f.sha)) || !Number.isInteger(f.size) || f.size < 0 || f.size > 5242880) return 'bad file sha or size';
  return '';
}
let refused = '';
if (path === null) refused = 'that address is not Vercel\'s API';
else if (/[?#%\\]|\.\.|\/\//.test(path)) refused = 'that kind of address is not allowed (options go in query)';
else if (!allowed.some(([m, re]) => m === method && re.test(path))) refused = method + ' ' + path + ' is not something Ahab may do on Vercel';
else if (!only(query, QUERY_KEYS) || !Object.values(query).every(v => /^[A-Za-z0-9_-]{1,64}$/.test(String(v)))) refused = 'only these options are allowed: ' + QUERY_KEYS.join(', ');
else if (method === 'GET' && bodyText !== '{}') refused = 'reading takes no body';
else if (path === 'v11/projects' && !(only(body, ['name', 'framework']) && new RegExp('^' + NAME + '$').test(String(body.name)) && (body.framework ?? null) === null)) refused = 'a new project takes only a name (and no framework)';
else if (path === 'v2/files' && !(only(body, ['data', 'digest']) && /^[0-9a-f]{40}$/.test(String(body.digest)) && typeof body.data === 'string' && /^[A-Za-z0-9+\/]*={0,2}$/.test(body.data) && body.data.length <= 7000000)) refused = 'an upload is just the file (base64) and its sha1';
else if (path === 'v13/deployments') {
  const publish = isObject(body) && 'deploymentId' in body;
  if (publish && !(only(body, ['name', 'project', 'deploymentId', 'target', 'projectSettings']) && Object.keys(body).length === 5)) refused = 'publishing takes only name, project, deploymentId, target and projectSettings';
  else if (!publish && !only(body, ['name', 'project', 'files', 'projectSettings'])) refused = 'a deployment takes only name, project, files and projectSettings (no target, no Git)';
  else if (!new RegExp('^' + NAME + '$').test(String(body.name)) || body.project !== body.name) refused = 'the deployment must name its project';
  else if (JSON.stringify(body.projectSettings) !== '{"framework":null}') refused = 'projectSettings must be {"framework": null}: static files, no build';
  else if (publish) refused = new RegExp('^' + DPL + '$').test(String(body.deploymentId)) && body.target === 'production' ? '' : 'publishing redeploys one deployment (dpl_...) as production';
  else if (!Array.isArray(body.files) || body.files.length < 1 || body.files.length > 500) refused = 'a deployment needs 1 to 500 files';
  else refused = body.files.map(badFile).find(Boolean) || '';
}
const upload = !refused && path === 'v2/files';
return [{ json: { method, url, query, body: upload ? {} : body, write: method !== 'GET', upload,
                  digest: upload ? body.digest : '', data: upload ? body.data : '', refused } }];

// Turn the upload's base64 into the raw file the next node sends.
const j = $input.first().json;
return [{ json: { url: j.url, digest: j.digest, query: j.query },
          binary: { file: { data: j.data, mimeType: 'application/octet-stream', fileName: j.digest } } }];
